import app from 'flarum/forum/app';
import RedirectToHomeAndOpenModalPage from './RedirectToHomeAndOpenModalPage';
export default class LoginPage extends RedirectToHomeAndOpenModalPage {
  createModal() {
    if (!app.session.user) {
      return () => flarum.reg.asyncModuleImport('flarum/forum/components/LogInModal');
    }
  }
}
flarum.reg.add('fof-direct-links', 'forum/components/LoginPage', LoginPage);